import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
const NIVEAUX_ETUDIANT = ['Primaire', 'Collège 1ère', 'Collège 2ème', 'Collège 3ème', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université L1', 'Université L2', 'Université L3', 'Master'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [structure, setStructure] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    fetchProfileData();
  }, [user]);

  const fetchProfileData = async () => {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      const res = await api.get(route);
      setForm(res.data);

      if (user?.role === 'professeur') {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur chargement profil", e);
      setLoading(false);
    }
  };

  const isSelected = (matId, nivId) => form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);
  const getTarif = (matId, nivId) => form.tarifs_matieres?.find(t => t.matiere_id === matId && t.niveau_id === nivId)?.tarif || '';

  const handleToggleMatiere = (matId, nivId) => {
    let updated = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) {
      updated = updated.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    } else {
      updated.push({ matiere_id: matId, niveau_id: nivId, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handlePriceChange = (matId, nivId, price) => {
    const updated = form.tarifs_matieres.map(t => 
      (t.matiere_id === matId && t.niveau_id === nivId) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      await api.put(route, {
        nom: form.user_nom, prenom: form.user_prenom, ville: form.ville,
        niveau: form.niveau, telephone: form.telephone, bio: form.bio,
        tarifs_complets: form.tarifs_matieres 
      });
      setSaved(true); setTimeout(() => setSaved(false), 2000);
    } catch (e) { alert('Erreur sauvegarde'); }
  }

  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setForm({ ...form, photo_url: res.data.url });
      alert("✅ Photo mise à jour !");
    } catch (e) { alert("Erreur photo"); }
  };

  const handleCertUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('description', newCert.description);
    formData.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setShowCertModal(false); fetchProfileData();
    } catch (e) { alert("Erreur certificat"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', width: '100%', outline: 'none' };

  if (loading) return <div style={{padding: 50, textAlign: 'center'}}>Chargement du profil...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 110, height: 110, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://ui-avatars.com/api/?name=' + form.user_prenom} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 5, right: 5, background: 'var(--accent)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷 <input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.8rem' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)' }}>{form.email} • <span style={{ color: 'var(--accent)' }}>{user?.role}</span></p>
          {user?.role === 'professeur' && <span style={{ background: 'rgba(108,99,255,0.1)', color: 'var(--accent)', padding: '4px 12px', borderRadius: 20, fontSize: '.75rem', fontWeight: 700 }}>{form.statut_validation?.toUpperCase()}</span>}
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '400px 1fr' : '1fr', gap: 30 }}>

        {/* COLONNE INFOS */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>👤 Identité</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
               <input style={inp} value={form.user_prenom || ''} placeholder="Prénom" onChange={e => setForm({...form, user_prenom: e.target.value})} />
               <input style={inp} value={form.user_nom || ''} placeholder="Nom" onChange={e => setForm({...form, user_nom: e.target.value})} />
               <select style={inp} value={form.ville || ''} onChange={e => setForm({...form, ville: e.target.value})}>
                    <option value="">Ville...</option>
                    {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
               </select>
               <input style={inp} placeholder="Téléphone" value={form.telephone || ''} onChange={e => setForm({...form, telephone: e.target.value})} />
               <button onClick={handleSave} style={{ background: 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600, cursor: 'pointer' }}>
                  {saved ? '✅ Mis à jour' : 'Sauvegarder mon profil'}
               </button>
            </div>
          </div>

          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
                <h3 style={{ marginBottom: 16 }}>📜 Mes Diplômes</h3>
                <div style={{ display: 'grid', gap: 10 }}>
                    {form.certificats?.map(c => (
                        <div key={c.id} style={{ background: 'var(--surface2)', padding: 12, borderRadius: 12, border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between' }}>
                            <span style={{ fontWeight: 600, fontSize: '.85rem' }}>{c.titre}</span>
                            <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)' }}>👁️</a>
                        </div>
                    ))}
                    <button onClick={() => setShowCertModal(true)} style={{ border: '2px dashed var(--border)', background: 'none', color: 'var(--accent)', padding: 15, borderRadius: 12, cursor: 'pointer' }}>+ Ajouter</button>
                </div>
            </div>
          )}
        </div>

        {/* COLONNE MATIÈRES (LA CASCADE) */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
            {structure.map(dom => (
              <div key={dom.id} style={{ marginBottom: 30 }}>
                <h4 style={{ color: 'var(--accent)', marginBottom: 15, borderBottom: '1px solid var(--border)', paddingBottom: 5 }}>📂 {dom.nom}</h4>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
                  {dom.niveaux?.map(niv => (
                    <div key={niv.id} style={{ background: 'var(--surface2)', padding: 15, borderRadius: 15 }}>
                      <div style={{ fontWeight: 700, marginBottom: 10, fontSize: '.9rem' }}>🎓 {niv.nom}</div>
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                        {niv.matieres?.map(mat => {
                          const selected = isSelected(mat.id, niv.id);
                          return (
                            <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: selected ? 'rgba(108,99,255,0.05)' : 'var(--card)', padding: '8px 12px', borderRadius: 10, border: selected ? '1px solid var(--accent)' : '1px solid transparent' }}>
                                <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.8rem', cursor: 'pointer' }}>
                                  <input type="checkbox" checked={selected} onChange={() => handleToggleMatiere(mat.id, niv.id)} />
                                  {mat.nom}
                                </label>
                                {selected && (
                                  <input type="number" value={getTarif(mat.id, niv.id)} onChange={(e) => handlePriceChange(mat.id, niv.id, e.target.value)} style={{ width: 50, background: 'var(--bg)', color: '#fff', border: '1px solid var(--border)', textAlign: 'center', borderRadius: 5 }} />
                                )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
            <button onClick={handleSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 16, borderRadius: 15, fontWeight: 700, cursor: 'pointer' }}>Enregistrer mon catalogue</button>
          </div>
        )}
      </div>

      {/* MODALE CERTIF */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ background: 'var(--surface)', padding: 30, borderRadius: 24, width: 400, border: '1px solid var(--border)' }}>
                <h3>Nouveau Diplôme</h3>
                <form onSubmit={handleCertUpload} style={{ display: 'flex', flexDirection: 'column', gap: 15, marginTop: 20 }}>
                    <input style={inp} placeholder="Titre du diplôme" onChange={e => setNewCert({...newCert, titre: e.target.value})} required />
                    <input type="file" onChange={e => setSelectedFile(e.target.files[0])} required />
                    <div style={{ display: 'flex', gap: 10 }}>
                        <button type="submit" style={{ flex: 1, background: 'var(--accent)', color: '#fff', padding: 12, borderRadius: 12, border: 'none' }}>Enregistrer</button>
                        <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', padding: 12, borderRadius: 12, border: 'none' }}>Annuler</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}
